from itertools import product
from typing import Dict, List, Tuple

Var = Tuple[int, int]
Literal = Tuple[Var, bool]
Clause = List[Literal]

def build_php_cnf(n: int) -> List[Clause]:
    clauses: List[Clause] = []
    for p in range(n + 1):
        clauses.append([((p, h), True) for h in range(n)])
    for h in range(n):
        for p1 in range(n + 1):
            for p2 in range(n + 1):
                if p1 != p2:
                    clauses.append([((p1, h), False), ((p2, h), False)])
    return clauses

def php_is_unsatisfiable(n: int) -> bool:
    cnf = build_php_cnf(n)
    variables = [(p, h) for p in range(n + 1) for h in range(n)]
    for bits in product([False, True], repeat=len(variables)):
        a: Dict[Var, bool] = dict(zip(variables, bits))
        if all(any(a[v] == pol for (v, pol) in c) for c in cnf):
            return False
    return True

for n in range(1, 4):
    print(n, php_is_unsatisfiable(n))

from typing import Dict, Tuple

Var = Tuple[int, int]

def counting_refutation(n: int, x: Dict[Var, int]) -> Tuple[int, int, int]:
    for p in range(n + 1):
        assert sum(x[(p, h)] for h in range(n)) >= 1
    for h in range(n):
        assert sum(x[(p, h)] for p in range(n + 1)) <= 1
    total = sum(x[(p, h)] for p in range(n + 1) for h in range(n))
    return n + 1, total, n  # n+1 <= total <= n  is impossible

# Any row-satisfying assignment forces a column overflow; the
# symbolic refutation is n+1 <= n, false for every n.
for n in (3, 5, 8):
    print(f'n={n}: refutation chain {n+1} <= total <= {n} (impossible)')

from math import ceil
from typing import List

def add_sound(c1: List[int], c2: List[int], d1: int, d2: int,
              x: List[int]) -> bool:
    l1 = sum(a * xi for a, xi in zip(c1, x))
    l2 = sum(a * xi for a, xi in zip(c2, x))
    if not (d1 <= l1 and d2 <= l2):
        return True
    return d1 + d2 <= sum((a + b) * xi for a, b, xi in zip(c1, c2, x))

def cg_rounding_sound(c: List[int], d: int, k: int, x: List[int]) -> bool:
    assert k > 0 and all(ci % k == 0 for ci in c)
    if not (d <= sum(ci * xi for ci, xi in zip(c, x))):
        return True
    return ceil(d / k) <= sum((ci // k) * xi for ci, xi in zip(c, x))

print(add_sound([2,0,1],[1,3,0],1,2,[1,1,1]))
print(cg_rounding_sound([6,6,6],7,6,[1,0,1]))

