function BUILD_PHP(n):
    clauses <- empty list
    for p in 0..n:                       # n+1 pigeons
        clauses.append( OR_{h in 0..n-1} x[p,h] )   # pigeon clause
    for h in 0..n-1:                     # n holes
        for p1 in 0..n:
            for p2 in 0..n:
                if p1 != p2:
                    clauses.append( (NOT x[p1,h]) OR (NOT x[p2,h]) )
    return clauses

